import os
from pathlib import Path

print("=== Workspace root ===")
for p in sorted(Path(".").iterdir()):
    print(("DIR " if p.is_dir() else "FILE") + " " + str(p))

print("\n=== Skill scripts dir ===")
scripts_dir = Path(".codex/skills/docx/scripts")
if scripts_dir.exists():
    for p in sorted(scripts_dir.iterdir()):
        print(("DIR " if p.is_dir() else "FILE") + " " + str(p))
else:
    print("scripts dir not found")

print("\n=== Skill root ===")
for p in sorted(Path(".codex/skills/docx").iterdir()):
    print(("DIR " if p.is_dir() else "FILE") + " " + str(p))

print("\n=== ooxml dir ===")
ooxml_dir = Path(".codex/skills/docx/ooxml")
if ooxml_dir.exists():
    for p in sorted(ooxml_dir.rglob("*")):
        print(("DIR " if p.is_dir() else "FILE") + " " + str(p.relative_to(ooxml_dir)))

